"""Editable table layouts transcribed from the supplied NBA Annexure II."""


def _table(key, title, columns, row_labels=(), header_groups=(), row_data=()):
    rows = [[label, *([""] * (len(columns) - 1))] for label in row_labels]
    if row_data:
        rows = [list(row) for row in row_data]
    if not rows:
        rows = [[""] * len(columns)]
    return {"key": f"annexure_{key}", "title": title, "columns": columns, "rows": rows, "header_groups": header_groups}


